const CAP_RATIO = WORDMARK.capHeight / WORDMARK.em;

function round(n: number): number {
  return Math.round(n * 1000) / 1000;
}

function runWidth(run: GlyphRun, fontSize: number): number {
  return round(((run.xMax - run.xMin) * fontSize) / run.em);
}

function glyphRun(run: GlyphRun, x: number, baseline: number, fontSize: number, fill: string): string {
  const s = fontSize / run.em;
  return `<g transform="translate(${round(x - run.xMin * s)} ${round(baseline)}) scale(${round(s)})"><path d="${run.path}" fill="${fill}"/></g>`;
}

export function ink(tone: BrandTone): string {
  if (tone === "onDark") return BRAND.paper;
  if (tone === "mono") return "currentColor";
  return BRAND.navy;
}

export function accent(tone: BrandTone): string {
  return tone === "onDark" ? BRAND.goldSoft : BRAND.gold;
}

/** Navy pass tile with the gold Aperture P. */
export function tileMark(tone: Exclude<BrandTone, "mono"> = "onLight"): string {
  return `<rect width="32" height="32" rx="${TILE_RADIUS}" fill="${BRAND.navy}"/><path d="${P_TILE}" fill="${accent(tone)}" fill-rule="evenodd"/>`;
}

/** One-colour bare P; the prism counter is a true knockout. */
export function bareMark(tone: BrandTone = "mono"): string {
  return `<path d="${P_COMBINED}" fill="${ink(tone)}" fill-rule="evenodd"/>`;
}

export function markSvg(tone: BrandTone = "onLight", size = 32, label = "Prism Pass"): string {
  const body = tone === "mono" ? bareMark(tone) : tileMark(tone);
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 32 32" role="img" aria-label="${label}">${body}</svg>`;
}

export interface LockupOptions {
  tone?: BrandTone;
  descriptor?: boolean;
  /** Emblem height in SVG units. */
  markSize?: number;
}

export function horizontalLockupSvg({ tone = "onLight", descriptor = true, markSize = 72 }: LockupOptions = {}): string {
  const pad = markSize * 0.28;
  const gap = markSize * PROPORTIONS.gap;
  const wordFont = markSize * PROPORTIONS.wordmark;
  const descFont = markSize * PROPORTIONS.descriptor;
  const textX = pad + markSize + gap;
  const baseline = pad + markSize * 0.6;
  const descBaseline = baseline + descFont * 1.05;
  const wordWidth = runWidth(WORDMARK, wordFont);
  const descWidth = runWidth(DESCRIPTOR, descFont);
  const width = round(textX + Math.max(wordWidth, descriptor ? descWidth : 0) + pad);
  const height = round(pad + markSize + pad);

  let body = `<rect width="${width}" height="${height}" fill="none"/>`;
  body += `<g transform="translate(${round(pad)} ${round(pad)}) scale(${round(markSize / 32)})">${tone === "mono" ? bareMark(tone) : tileMark(tone)}</g>`;
  body += glyphRun(WORDMARK, textX, baseline, wordFont, ink(tone));
  if (descriptor) {
    const fill = tone === "onDark" ? BRAND.goldSoft : tone === "mono" ? "currentColor" : BRAND.muted;
    body += glyphRun(DESCRIPTOR, textX, descBaseline, descFont, fill);
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="Prism Pass">${body}</svg>`;
}

export function stackedLockupSvg({ tone = "onLight", descriptor = true, markSize = 96 }: LockupOptions = {}): string {
  const pad = markSize * 0.22;
  const wordFont = markSize * PROPORTIONS.wordmark;
  const descFont = markSize * PROPORTIONS.descriptor;
  const wordWidth = runWidth(WORDMARK, wordFont);
  const descWidth = runWidth(DESCRIPTOR, descFont);
  const contentWidth = Math.max(markSize, wordWidth, descriptor ? descWidth : 0);
  const width = round(contentWidth + pad * 2);
  const markX = round((width - markSize) / 2);
  const gap = markSize * PROPORTIONS.stackedGap;
  const baseline = pad + markSize + gap + wordFont * CAP_RATIO;
  const descBaseline = baseline + descFont * 1.15;
  const height = round(descBaseline + (descriptor ? pad * 0.8 : pad));

  let body = `<rect width="${width}" height="${height}" fill="none"/>`;
  body += `<g transform="translate(${markX} ${round(pad)}) scale(${round(markSize / 32)})">${tone === "mono" ? bareMark(tone) : tileMark(tone)}</g>`;
  body += glyphRun(WORDMARK, (width - wordWidth) / 2, baseline, wordFont, ink(tone));
  if (descriptor) {
    const fill = tone === "onDark" ? BRAND.goldSoft : tone === "mono" ? "currentColor" : BRAND.muted;
    body += glyphRun(DESCRIPTOR, (width - descWidth) / 2, descBaseline, descFont, fill);
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="Prism Pass">${body}</svg>`;
}

/** Transparent lockup for the OG image: mark + wordmark, no descriptor. */
export function ogLockupSvg(): string {
  return horizontalLockupSvg({ tone: "onDark", descriptor: false, markSize: 80 });
}

/** One-line value proposition, outlined so the OG image is font-independent. */
export function ogValuePropSvg(): string {
  const fontSize = 66;
  const width = round(runWidth(VALUE_PROP, fontSize) + 2);
  const height = round(fontSize * 1.2);
  const baseline = round(fontSize * 0.95);
  const body = glyphRun(VALUE_PROP, 1, baseline, fontSize, BRAND.paper);
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="Unified attendance + verification">${body}</svg>`;
}
